import {readFileSync,writeFileSync} from 'node:fs';
import {gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const study='/tmp/engine-detector-overwrite-20261104',arm=process.argv[2],cwd=study+'/'+arm;
process.chdir(cwd);process.env.LR_ENGINE='wasm';
const {LineRiderEngine:Engine}=await import(cwd+'/scripts/lib/native_motion/engine.ts');
const original=Engine.prototype.getBallisticStateAtFrame;let calls=0,cached=0;
Engine.prototype.getBallisticStateAtFrame=function(frame:number){calls++;if(this.getLastFrameIndex()>=frame)cached++;return original.call(this,frame);};
const {compileHandoff}=await import(cwd+'/scripts/v0/optimizer/handoff.ts');
const {loadCatalog}=await import(cwd+'/benchmark/v6/model.ts');
const {policy}=await import(cwd+'/benchmark/v6/policy.ts');
const {caseSpec}=await import(cwd+'/benchmark/v4/model.ts');
const {getFrameCount,getPhysicsFrameCount}=await import(cwd+'/scripts/lib/detector.ts');
const cell=JSON.parse(readFileSync(cwd+'/tools/parity/cells.json','utf8')).cells[61];
const catalog=loadCatalog(),c=catalog.cases.find((c:any)=>c.id===cell.id),music=catalog.music.find((m:any)=>m.id===c.sourceId),requested=c.plans[cell.seed];
const checkpoint=compileHandoff(caseSpec(music),cell.seed,{budget:cell.budget??policy.budget,impactContract:'line.strike.v3',creative:requested.preferences});
const json=JSON.stringify(checkpoint),hash=(s:string)=>createHash('sha256').update(s).digest('hex');
assert.equal(hash(JSON.stringify(checkpoint.track)),cell.trackHash);assert.equal(checkpoint.stats.sim_frames,cell.physicalFrames);
writeFileSync(study+'/'+arm+'-checkpoint.json.gz',gzipSync(json));
const result={arm,status:'PASS',fullStateReads:calls,cachedFullStateReads:cached,integratingFullStateReads:calls-cached,
 trackHash:cell.trackHash,physicalFrames:checkpoint.stats.sim_frames,readCounter:getFrameCount(),finalPhysicsCounter:getPhysicsFrameCount(),checkpointSha256:hash(json)};
writeFileSync(study+'/'+arm+'-capture.json',JSON.stringify(result,null,2)+'\n');console.log(result);

