 arms[arm]={'sampledBytesPerCompile':sum(counts.values())/3,
   'scanFramesBytesPerCompile':sum(size for (name,_),size in counts.items() if name=='scanFrames')/3,
   'top': [{'name':name,'url':url,'sampledBytesPerCompile':size/3} for (name,url),size in counts.most_common(30)]}
