 'arms':arms,'totalSampledChangePct':100*(arms['candidate']['sampledBytesPerCompile']/arms['reference']['sampledBytesPerCompile']-1)}
(r/'heap-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print({arm:{key:round(value/1048576,3) for key,value in row.items() if key!='top'} for arm,row in arms.items()})
print('total sampled allocation change percent',summary['totalSampledChangePct'])

a=arms['reference']['scanFramesBytesPerCompile'];b=arms['candidate']['scanFramesBytesPerCompile'];gate={'referenceBytes':a,'candidateBytes':b,'reduction':1-b/a,'requiredReduction':.25,'passed':1-b/a>=.25};(r/'allocation-gate.json').write_text(json.dumps(gate,indent=2)+'\n');print(gate)

